import styled from '@emotion/styled';
import CoverBackground from 'assets/img/cover-background.svg';

export const StyledSubCoverContainer = styled.div`
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 938px;
  padding: 0 160px;
  background: #000000 url(${CoverBackground}) center / cover no-repeat;
`;

export const StyledSubCoverContent = styled.div`
  margin-top: 400px;
  display: flex;
  flex-direction: column;
  gap: 16px;
`;

export const StyledSubCoverHeading = styled.h2`
  color: #ffffff;
  font-family: 'Barlow', sans-serif;
  font-weight: 600;
  font-size: 64px;
  line-height: 112%;
  letter-spacing: 0px;
  margin: 0;
`;

export const StyledSubCoverBadge = styled.div`
  background: #ffffff;
  padding: 12px 22px;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  border-radius: 36px;
  width: max-content;
`;

export const StyledSubCoverBadgeText = styled.span`
  font-family: 'Barlow', sans-serif;
  font-weight: 600;
  font-size: 24px;
  line-height: 120%;
`;
